/**
 * Direction vocabulary types for Surface Transit.
 *
 * Pure data shapes shared by the direction seam and corridor geometry.
 * No effects, no imports.
 */
export interface RouteDirectionOption {
  readonly directionId: number;
  readonly label: string;
  readonly destination: string;
  /** Present only when Core supplied this label instead of operator text. */
  readonly generatedLabel?: GeneratedDirectionLabel;
}

/** Semantic identity of a direction label generated by Core. */
export type GeneratedDirectionLabel =
  | "northbound"
  | "southbound"
  | "eastbound"
  | "westbound"
  | "outbound"
  | "inbound";

/**
 * Direction-facing text pair derived from live-headsign parsing (and accepted
 * by direction-label enrichment). Names the former anonymous
 * `{ label, destination }` data clump.
 */
export interface ParsedHeadsign {
  readonly label: string;
  readonly destination: string;
  /** Propagated only for labels generated from route geometry/defaults. */
  readonly generatedLabel?: GeneratedDirectionLabel;
}

/**
 * A rider's stop target, resolved against an ordered corridor stop list.
 */
export interface RiderStop {
  readonly id?: string;
  readonly code?: string;
  readonly lat?: number;
  readonly lon?: number;
}

/**
 * Compass axis a route's two directions run along. Resolved from the agency's
 * directionInference policy (routeOverrides[routeId] ?? default); absent
 * means the route type's own canonical pair applies.
 */
export type DirectionAxis = "east-west" | "north-south";
